package repopolicy

import "testing"

// TestNormalizeOrigin_LocalRemotesGetDistinctKeys closes the gap behind the
// path-trust fallback.
//
// TrustIdentity's contract is "new destination, new consent" — a re-election to
// another remote changes the key and re-asks. A filesystem remote used to
// normalize to "", which dropped the identity to the WORKTREE PATH. Two
// different local mirrors then shared one key, so consent recorded while
// pushing to one silently covered the other: same path, same trust.
//
// Every hosted URL form already normalizes; filesystem remotes were the only
// shape that did not, which is why this was the whole of the fallback in
// practice.
func TestNormalizeOrigin_LocalRemotesGetDistinctKeys(t *testing.T) {
	t.Parallel()

	a := NormalizeOrigin("/srv/git/alpha.git")
	b := NormalizeOrigin("/srv/git/beta.git")

	if a == "" || b == "" {
		t.Fatalf("a filesystem remote must produce a key, got %q and %q", a, b)
	}
	if a == b {
		t.Errorf("two different local mirrors must not share a trust key: %q == %q", a, b)
	}
}

// TestNormalizeOrigin_LocalRemoteFormsAgree keeps the spellings of one mirror
// on a single key, so consent survives a cosmetic change to the remote URL.
func TestNormalizeOrigin_LocalRemoteFormsAgree(t *testing.T) {
	t.Parallel()

	plain := NormalizeOrigin("/srv/git/alpha.git")
	withScheme := NormalizeOrigin("file:///srv/git/alpha.git")
	if plain != withScheme {
		t.Errorf("file:// and bare path forms must agree: %q vs %q", plain, withScheme)
	}
}

// TestNormalizeOrigin_HostedFormsUnchanged pins that this did not disturb the
// existing keys.
func TestNormalizeOrigin_HostedFormsUnchanged(t *testing.T) {
	t.Parallel()

	for _, tc := range []struct{ in, want string }{
		{"https://github.com/o/r.git", "github.com/o/r"},
		{"git@github.com:o/r.git", "github.com/o/r"},
		{"entire://aws-us-east-2.entire.io/gh/o/r", "github.com/o/r"},
		{"", ""},
	} {
		if got := NormalizeOrigin(tc.in); got != tc.want {
			t.Errorf("NormalizeOrigin(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}
EOF
