func NormalizeOrigin(rawURL string) string {
	if rawURL == "" {
		return ""
	}
	info, err := gitremote.ParseURL(rawURL)
	if err != nil || info == nil || info.Owner == "" || info.Repo == "" {
		// A filesystem remote — a local mirror or bare repo on a NAS. Every
		// HOSTED form (https, ssh, scp-style, entire://) parses above; this is
		// the only shape that reaches here in practice.
		//
		// Key it rather than returning "", because "" drops the identity to the
		// worktree PATH, and two different local mirrors then share one key:
		// consent recorded while pushing to one silently covers the other. The
		// type's contract is "new destination, new consent", and a path cannot
		// tell two destinations apart.
		return localRemoteKey(rawURL)
	}
	host := info.CanonicalHost()
	if host == "" {
		return ""
	}
	return strings.ToLower(host + "/" + info.Owner + "/" + info.Repo)
}

