// TestIsActiveAtRoot pins the predicate a decision about a FOREIGN repo needs:
// a hook process cannot ask "is Entire on here?" about a repo it is not running
// in, and neither half of the answer survives being simplified.
//
// Presence of a settings file is not the first half: `entire disable` leaves
// the file in place, so a presence check made the disable veto that binding
// adoption claims to honor never fire. And the second half has no file at all —
// a globally tracked repo is tracked precisely because the user asked for it
// machine-wide rather than per repo.
func TestIsActiveAtRoot(t *testing.T) {
	// No t.Parallel: each case sets ENTIRE_CONFIG_DIR for the global tier.
	for _, tc := range []struct {
		name         string
		userSettings string            // user-global settings.json body, "" for none
		write        map[string]string // repo-relative path -> contents
		expected     bool
	}{
		{
			name:     "never set up, global tier off",
			expected: false,
		},
		{
			name:     "enabled in the project file",
			write:    map[string]string{EntireSettingsFile: `{"enabled":true}`},
			expected: true,
		},
		{
			// The case the disable veto exists for.
			name:     "explicitly disabled in the project file",
			write:    map[string]string{EntireSettingsFile: `{"enabled":false}`},
			expected: false,
		},
		{
			name:     "enabled only in the local file",
			write:    map[string]string{EntireSettingsLocalFile: `{"enabled":true}`},
			expected: true,
		},
		{
			// The local layer is the developer's own, so its disable wins over
			// a project file that enables.
			name: "local disable overrides a project enable",
			write: map[string]string{
				EntireSettingsFile:      `{"enabled":true}`,
				EntireSettingsLocalFile: `{"enabled":false}`,
			},
			expected: false,
		},
		{
			// Fail closed: an unreadable repo is not a repo we may write to.
			name:     "malformed settings are not active",
			write:    map[string]string{EntireSettingsFile: `{"enabled":true`},
			expected: false,
		},
		{
			// The half a settings-file check cannot see at all.
			name:         "no repo setup, covered by the global tier",
			userSettings: `{"global":{"enabled":true}}`,
			expected:     true,
		},
		{
			// A repo-level disable is a veto over the global tier too.
			name:         "explicitly disabled beats the global tier",
			userSettings: `{"global":{"enabled":true}}`,
			write:        map[string]string{EntireSettingsFile: `{"enabled":false}`},
			expected:     false,
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			configDir := t.TempDir()
			t.Setenv("ENTIRE_CONFIG_DIR", configDir)
			if tc.userSettings != "" {
				if err := os.WriteFile(filepath.Join(configDir, UserSettingsFileName),
					[]byte(tc.userSettings), 0o600); err != nil {
					t.Fatal(err)
				}
			}

			root := t.TempDir()
			for rel, body := range tc.write {
				path := filepath.Join(root, rel)
				if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
					t.Fatal(err)
				}
			}

			if got := IsActiveAtRoot(context.Background(), root); got != tc.expected {
				t.Errorf("IsActiveAtRoot() = %v, want %v", got, tc.expected)
			}
		})
	}
}
